import {
  $getNodeByKey,
  $getSelection,
  $isRangeSelection,
  $isTextNode,
  $setCompositionKey,
  type BaseSelection,
  BLUR_COMMAND,
  COMMAND_PRIORITY_LOW,
  COMPOSITION_END_TAG,
  COMPOSITION_START_COMMAND,
  defineExtension,
  type EditorState,
  getActiveElement,
  isHTMLElement,
  KEY_ARROW_RIGHT_COMMAND,
  KEY_TAB_COMMAND,
  type LexicalEditor,
  mergeRegister,
  type NodeKey,
  registerEventListener,
  safeCast,
  setDOMUnmanaged,
} from "lexical";

import {
  effect,
  IMEExtension,
  namedSignals,
  RootElementExtension,
  shallowMergeConfig,
  WatchEditableExtension,
} from "@lexical/extension";
import { $isAtNodeEnd } from "@lexical/selection";

import { locales } from "@/components/editor/locales";
import type { Language } from "@/components/editor/plugins/i18n-plugin";

export interface AutocompleteDictionary {
  readonly minPrefixLength: number;
  query(prefix: string): null | string;
}

export interface WordlistDictionaryOptions {
  minPrefixLength?: number;
  caseSensitive?: boolean;
}

export function createWordlistDictionary(
  words: readonly string[],
  options: WordlistDictionaryOptions = {},
): AutocompleteDictionary {
  const { minPrefixLength = 2, caseSensitive = false } = options;
  const fold = (text: string): string =>
    caseSensitive ? text : text.toLowerCase();
  const folded = words.map(fold);
  const order = Uint32Array.from(
    words
      .map((_, index) => index)
      .sort((a, b) =>
        folded[a] < folded[b] ? -1 : folded[a] > folded[b] ? 1 : a - b,
      ),
  );
  return {
    minPrefixLength,
    query(prefix: string): null | string {
      if (prefix.length < minPrefixLength) {
        return null;
      }
      const needle = fold(prefix);
      let lo = 0;
      let hi = order.length;
      while (lo < hi) {
        const mid = (lo + hi) >>> 1;
        if (fold(words[order[mid]]) < needle) {
          lo = mid + 1;
        } else {
          hi = mid;
        }
      }
      let bestIndex = -1;
      let bestWord: string | null = null;
      for (let k = lo; k < order.length; k++) {
        const index = order[k];
        const word = words[index];
        if (!fold(word).startsWith(needle)) {
          break;
        }
        if (
          word.length > prefix.length &&
          (bestIndex === -1 || index < bestIndex)
        ) {
          bestIndex = index;
          bestWord = word;
        }
      }
      return bestWord === null ? null : bestWord.substring(prefix.length);
    },
  };
}

function isArabic(cp: number): boolean {
  return (
    (cp >= 0x0600 && cp <= 0x06ff) ||
    (cp >= 0x0750 && cp <= 0x077f) ||
    (cp >= 0x08a0 && cp <= 0x08ff) ||
    (cp >= 0xfb50 && cp <= 0xfdff) ||
    (cp >= 0xfe70 && cp <= 0xfeff)
  );
}

function isHebrew(cp: number): boolean {
  return (cp >= 0x0590 && cp <= 0x05ff) || (cp >= 0xfb1d && cp <= 0xfb4f);
}

function isZeroWidthOrControl(cp: number): boolean {
  return (
    cp < 0x20 ||
    (cp >= 0x200b && cp <= 0x200f) ||
    (cp >= 0x202a && cp <= 0x202e) ||
    cp === 0xfeff
  );
}

export function detectLanguage(text: string): string {
  const codePoints = Array.from(text);
  for (let i = codePoints.length - 1; i >= 0; i--) {
    const cp = codePoints[i].codePointAt(0);
    if (cp === undefined || isZeroWidthOrControl(cp)) {
      continue;
    }
    if (isArabic(cp)) {
      return "ar";
    }
    if (isHebrew(cp)) {
      return "he";
    }
    return "en";
  }
  return "en";
}

export type AutocompleteDictionaryLoader =
  () => Promise<AutocompleteDictionary>;

export const defaultDictionaries: Readonly<
  Record<string, AutocompleteDictionaryLoader>
> = {
  ar: () =>
    import("@/components/editor/dictionaries/arabic").then(({ ARABIC_WORDS }) =>
      createWordlistDictionary(ARABIC_WORDS),
    ),
  en: () =>
    import("@/components/editor/dictionaries/english").then(
      ({ ENGLISH_WORDS }) =>
        createWordlistDictionary(ENGLISH_WORDS, { minPrefixLength: 4 }),
    ),
  he: () =>
    import("@/components/editor/dictionaries/hebrew").then(({ HEBREW_WORDS }) =>
      createWordlistDictionary(HEBREW_WORDS),
    ),
};

const DEFAULT_COMPOSITION_IDLE_DEBOUNCE_MS = 200;

const QUERY_LATENCY_MS = 200;

const AUTOCOMPLETE_GHOST_ATTR = "data-autocomplete-ghost";

function $search(selection: null | BaseSelection): [boolean, string] {
  if (!$isRangeSelection(selection) || !selection.isCollapsed()) {
    return [false, ""];
  }
  const node = selection.getNodes()[0];
  const anchor = selection.anchor;
  if (!$isTextNode(node) || !node.isSimpleText() || !$isAtNodeEnd(anchor)) {
    return [false, ""];
  }
  const word = [];
  const text = node.getTextContent();
  let i = node.getTextContentSize();
  let c;
  while (i-- && i >= 0 && (c = text[i]) !== " ") {
    word.push(c);
  }
  if (word.length === 0) {
    return [false, ""];
  }
  return [true, word.reverse().join("")];
}

function query(
  dictionaryPromise: Promise<AutocompleteDictionary | undefined>,
  searchText: string,
  signal: AbortSignal,
): Promise<null | string> {
  return new Promise((resolve, reject) => {
    if (signal.aborted) {
      reject(signal.reason);
      return;
    }
    const onAbort = () => {
      clearTimeout(timeout);
      reject(signal.reason);
    };
    const timeout = setTimeout(async () => {
      signal.removeEventListener("abort", onAbort);
      let dictionary: AutocompleteDictionary | undefined;
      try {
        dictionary = await dictionaryPromise;
      } catch (e) {
        reject(e);
        return;
      }
      if (signal.aborted) {
        reject(signal.reason);
        return;
      }
      if (dictionary === undefined) {
        resolve(null);
        return;
      }
      resolve(dictionary.query(searchText));
    }, QUERY_LATENCY_MS);
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

export function extractTrailingWord(text: string): string {
  const trimmed = text.replace(/\s+$/u, "");
  const match = trimmed.match(/\S+$/u);
  return match === null ? "" : match[0];
}

export function getCompositionTextFromDOM(dom: HTMLElement): string {
  let text = "";
  for (const node of dom.childNodes) {
    if (node.nodeType === Node.TEXT_NODE) {
      text += node.textContent ?? "";
    } else if (
      isHTMLElement(node) &&
      !node.hasAttribute(AUTOCOMPLETE_GHOST_ATTR)
    ) {
      text += node.textContent ?? "";
    }
  }
  return text.replace(/[\u200B-\u200D\uFEFF]/g, "");
}

function formatSuggestionText(
  suggestion: string,
  rootElem: HTMLElement | null,
): string {
  const userAgentData = (
    window.navigator as Navigator & { userAgentData?: { mobile: boolean } }
  ).userAgentData;
  const isMobile =
    userAgentData !== undefined
      ? userAgentData.mobile
      : window.innerWidth <= 800 && window.innerHeight <= 600;

  if (!isMobile) {
    return `${suggestion} (TAB)`;
  }
  const lang = rootElem?.closest<HTMLElement>("[lang]")?.lang ?? "en";
  const isRTL =
    rootElem !== null && getComputedStyle(rootElem).direction === "rtl";
  const swipeWord = (locales[lang as Language] ?? locales.en).autocompleteSwipe;
  return `${suggestion} (${swipeWord} ${isRTL ? "⬅" : "⮕"})`;
}

function syncGhost(
  editor: LexicalEditor,
  textNodeKey: NodeKey | null,
  ghostText: string | null,
): void {
  const root = editor.getRootElement();
  if (root) {
    for (const el of root.querySelectorAll(`[${AUTOCOMPLETE_GHOST_ATTR}]`)) {
      el.remove();
    }
  }
  if (textNodeKey === null || ghostText === null) {
    return;
  }
  const dom = editor.getElementByKey(textNodeKey);
  if (!dom) {
    return;
  }
  const ghost = dom.ownerDocument.createElement("span");
  ghost.setAttribute(AUTOCOMPLETE_GHOST_ATTR, "true");
  ghost.setAttribute("contenteditable", "false");
  ghost.className = editor._config.theme.autocomplete || "";
  ghost.textContent = ghostText;
  setDOMUnmanaged(ghost);
  dom.appendChild(ghost);
}

function addSwipeRightListener(
  element: HTMLElement,
  cb: (force: number, e: TouchEvent) => void,
): () => void {
  let start: [number, number] | null = null;
  const readTouch = (e: TouchEvent): [number, number] | null => {
    const touch = e.changedTouches[0];
    return touch === undefined ? null : [touch.clientX, touch.clientY];
  };
  const handleTouchstart = (e: TouchEvent) => {
    start = readTouch(e);
  };
  const handleTouchend = (e: TouchEvent) => {
    if (start === null) {
      return;
    }
    const end = readTouch(e);
    if (end !== null) {
      const isRTL = getComputedStyle(element).direction === "rtl";
      const x = end[0] - start[0];
      const y = end[1] - start[1];
      const forward = isRTL ? -x : x;
      if (forward > 0 && forward > Math.abs(y)) {
        cb(forward, e);
      }
    }
  };
  element.addEventListener("touchstart", handleTouchstart);
  element.addEventListener("touchend", handleTouchend);
  return () => {
    element.removeEventListener("touchstart", handleTouchstart);
    element.removeEventListener("touchend", handleTouchend);
  };
}

export interface AutocompleteConfig {
  disabled: boolean;
  dictionaries: Readonly<Record<string, AutocompleteDictionaryLoader>>;
  detectLanguage: (text: string) => string;
  compositionIdleDebounceMs: number;
}

function mergeAutocompleteConfig(
  config: AutocompleteConfig,
  overrides: Partial<AutocompleteConfig>,
): AutocompleteConfig {
  const merged = shallowMergeConfig(config, overrides);
  if (overrides.dictionaries) {
    merged.dictionaries = {
      ...config.dictionaries,
      ...overrides.dictionaries,
    };
  }
  return merged;
}

export const AutocompleteExtension = defineExtension({
  name: "@shadcn-editor/editor/Autocomplete",
  build: (_editor, config) => namedSignals(config),
  config: safeCast<AutocompleteConfig>({
    compositionIdleDebounceMs: DEFAULT_COMPOSITION_IDLE_DEBOUNCE_MS,
    detectLanguage,
    dictionaries: defaultDictionaries,
    disabled: false,
  }),
  dependencies: [IMEExtension, RootElementExtension, WatchEditableExtension],
  mergeConfig: mergeAutocompleteConfig,
  register: (editor: LexicalEditor, _config, state) => {
    const ime = state.getDependency(IMEExtension).output;
    const editableSignal = state.getDependency(WatchEditableExtension).output;
    const rootElemSignal = state.getDependency(RootElementExtension).output;
    let activeTextNodeKey: NodeKey | null = null;
    let lastMatch: string | null = null;
    let lastSuggestion: string | null = null;
    let searchController: AbortController | null = null;
    let pendingCompositionTimer: number | null = null;
    const dictionaryCache = new Map<
      AutocompleteDictionaryLoader,
      Promise<AutocompleteDictionary>
    >();

    function loadDictionary(
      loader: AutocompleteDictionaryLoader | undefined,
    ): Promise<AutocompleteDictionary | undefined> {
      if (loader === undefined) {
        return Promise.resolve(undefined);
      }
      let cached = dictionaryCache.get(loader);
      if (cached === undefined) {
        cached = loader();
        dictionaryCache.set(loader, cached);
      }
      return cached;
    }

    function clearPendingCompositionTimer() {
      if (pendingCompositionTimer !== null) {
        clearTimeout(pendingCompositionTimer);
        pendingCompositionTimer = null;
      }
    }

    function isEditorFocused(): boolean {
      const rootElem = editor.getRootElement();
      const active = rootElem ? getActiveElement(rootElem) : null;
      return rootElem != null && active != null && rootElem.contains(active);
    }

    function dismiss() {
      activeTextNodeKey = null;
      lastMatch = null;
      lastSuggestion = null;
      if (searchController !== null) {
        searchController.abort();
        searchController = null;
      }
      syncGhost(editor, null, null);
    }

    function tryCompositionSuggestion() {
      pendingCompositionTimer = null;
      const composingNode = ime.composingTextNode.value;
      if (composingNode === null) {
        return;
      }
      const composingKey = composingNode.getKey();
      const dom = editor.getElementByKey(composingKey);
      if (dom === null) {
        return;
      }
      const text = getCompositionTextFromDOM(dom);
      if (text.length === 0) {
        return;
      }
      const prefix = extractTrailingWord(text);
      if (prefix.length === 0 || prefix === lastMatch) {
        return;
      }
      if (searchController !== null) {
        searchController.abort();
      }
      syncGhost(editor, null, null);
      lastMatch = prefix;
      lastSuggestion = null;
      activeTextNodeKey = null;
      const controller = new AbortController();
      searchController = controller;
      const language = output.detectLanguage.value(prefix);
      query(
        loadDictionary(output.dictionaries.value[language]),
        prefix,
        controller.signal,
      )
        .then((newSuggestion) => {
          applyCompositionSuggestion(
            controller,
            composingKey,
            prefix,
            newSuggestion,
          );
        })
        .catch((e) => {
          if (!(e instanceof DOMException && e.name === "AbortError")) {
            console.error(e);
          }
        });
    }

    function applyCompositionSuggestion(
      refController: AbortController,
      composingKey: NodeKey,
      prefix: string,
      newSuggestion: string | null,
    ) {
      const composingNode = ime.composingTextNode.value;
      if (
        searchController !== refController ||
        newSuggestion === null ||
        composingNode === null ||
        composingNode.getKey() !== composingKey
      ) {
        return;
      }
      const dom = editor.getElementByKey(composingKey);
      if (dom === null) {
        return;
      }
      if (extractTrailingWord(getCompositionTextFromDOM(dom)) !== prefix) {
        return;
      }
      activeTextNodeKey = composingKey;
      lastSuggestion = newSuggestion;
      syncGhost(
        editor,
        composingKey,
        formatSuggestionText(newSuggestion, editor.getRootElement()),
      );
    }

    function onCompositionUpdateDOM() {
      const debounceMs = output.compositionIdleDebounceMs.value;
      if (debounceMs <= 0) {
        return;
      }
      clearPendingCompositionTimer();
      pendingCompositionTimer = window.setTimeout(
        tryCompositionSuggestion,
        debounceMs,
      );
    }

    function onCompositionEndDOM() {
      clearPendingCompositionTimer();
      Promise.resolve().then(() => {
        handleUpdate({
          editorState: editor.getEditorState(),
          tags: new Set([COMPOSITION_END_TAG]),
        });
      });
    }

    function applyAsyncSuggestion(
      refController: AbortController,
      newSuggestion: string | null,
    ) {
      if (searchController !== refController || newSuggestion === null) {
        return;
      }
      if (!isEditorFocused()) {
        return;
      }
      editor.read("latest", () => {
        const selection = $getSelection();
        const [hasMatch, match] = $search(selection);
        if (!hasMatch || match !== lastMatch || !$isRangeSelection(selection)) {
          return;
        }
        const node = selection.getNodes()[0];
        if (!$isTextNode(node)) {
          return;
        }
        activeTextNodeKey = node.getKey();
        lastSuggestion = newSuggestion;
        syncGhost(
          editor,
          activeTextNodeKey,
          formatSuggestionText(newSuggestion, editor.getRootElement()),
        );
      });
    }

    function handleUpdate({
      editorState,
      tags,
    }: {
      editorState: EditorState;
      tags: Set<string>;
    }) {
      if (!isEditorFocused()) {
        dismiss();
        return;
      }
      if (!tags.has(COMPOSITION_END_TAG) && editor.isComposing()) {
        return;
      }
      editorState.read(
        () => {
          const selection = $getSelection();
          const [hasMatch, match] = $search(selection);
          if (!hasMatch) {
            dismiss();
            return;
          }
          if (match === lastMatch) {
            if ($isRangeSelection(selection)) {
              const node = selection.getNodes()[0];
              if ($isTextNode(node)) {
                const key = node.getKey();
                if (key !== activeTextNodeKey) {
                  activeTextNodeKey = key;
                  syncGhost(
                    editor,
                    activeTextNodeKey,
                    lastSuggestion
                      ? formatSuggestionText(
                          lastSuggestion,
                          editor.getRootElement(),
                        )
                      : null,
                  );
                }
              }
            }
            return;
          }
          if (searchController !== null) {
            searchController.abort();
          }
          syncGhost(editor, null, null);
          lastMatch = match;
          lastSuggestion = null;
          activeTextNodeKey = null;
          const controller = new AbortController();
          searchController = controller;
          const language = output.detectLanguage.value(match);
          query(
            loadDictionary(output.dictionaries.value[language]),
            match,
            controller.signal,
          )
            .then((newSuggestion) => {
              applyAsyncSuggestion(controller, newSuggestion);
            })
            .catch((e) => {
              if (!(e instanceof DOMException && e.name === "AbortError")) {
                console.error(e);
              }
            });
        },
        { editor },
      );
    }

    function $commitSuggestion(): boolean {
      if (activeTextNodeKey === null || lastSuggestion === null) {
        return false;
      }
      const node = $getNodeByKey(activeTextNodeKey);
      if (!$isTextNode(node)) {
        dismiss();
        return false;
      }
      const composingNode = ime.composingTextNode.value;
      if (
        composingNode !== null &&
        composingNode.getKey() === activeTextNodeKey
      ) {
        const dom = editor.getElementByKey(activeTextNodeKey);
        if (dom !== null) {
          const liveText = getCompositionTextFromDOM(dom);
          const fullText = liveText + lastSuggestion;
          node.setTextContent(fullText);
          $setCompositionKey(null);
          node.select();
          dismiss();
          return true;
        }
      }
      node.spliceText(node.getTextContentSize(), 0, lastSuggestion, true);
      dismiss();
      return true;
    }

    function $handleCommitCommand(event: Event): boolean {
      const didCommit = $commitSuggestion();
      if (didCommit) {
        event.preventDefault();
      }
      return didCommit;
    }

    function handleSwipeRight(_force: number, event: TouchEvent) {
      let didCommit = false;
      editor.update(
        () => {
          didCommit = $commitSuggestion();
        },
        { discrete: true },
      );
      if (didCommit) {
        event.preventDefault();
      }
    }

    const output = state.getOutput();
    return effect(() => {
      const rootElem = rootElemSignal.value;
      const editable = editableSignal.value;
      if (output.disabled.value || !rootElem || !editable) {
        return;
      }
      for (const loader of Object.values(output.dictionaries.value)) {
        loadDictionary(loader);
      }
      return mergeRegister(
        registerEventListener(
          rootElem,
          "compositionupdate",
          onCompositionUpdateDOM,
        ),
        registerEventListener(rootElem, "compositionend", onCompositionEndDOM),
        editor.registerUpdateListener(handleUpdate),
        editor.registerCommand(
          BLUR_COMMAND,
          () => {
            dismiss();
            return false;
          },
          COMMAND_PRIORITY_LOW,
        ),
        editor.registerCommand(
          COMPOSITION_START_COMMAND,
          () => {
            dismiss();
            return false;
          },
          COMMAND_PRIORITY_LOW,
        ),
        editor.registerCommand(
          KEY_TAB_COMMAND,
          $handleCommitCommand,
          COMMAND_PRIORITY_LOW,
        ),
        editor.registerCommand(
          KEY_ARROW_RIGHT_COMMAND,
          $handleCommitCommand,
          COMMAND_PRIORITY_LOW,
        ),
        addSwipeRightListener(rootElem, handleSwipeRight),
        clearPendingCompositionTimer,
        dismiss,
      );
    });
  },
});

import { configExtension, defineExtension } from "lexical";

import { $isCodeNode } from "@lexical/code-core";
import {
  autoLinkEmailMatcher,
  autoLinkUrlMatcher,
  AutoLinkExtension as LexicalAutoLinkExtension,
} from "@lexical/link";

export const AutoLinkExtension = defineExtension({
  name: "@shadcn-editor/editor/AutoLink",
  dependencies: [
    configExtension(LexicalAutoLinkExtension, {
      excludeParents: [$isCodeNode],
      matchers: [autoLinkUrlMatcher, autoLinkEmailMatcher],
    }),
  ],
});

import {
  $createNodeSelection,
  $createParagraphNode,
  $getAdjacentNode,
  $getSelection,
  $getSlot,
  $getSlotHost,
  $getSlotNameWithinHost,
  $isElementNode,
  $isParagraphNode,
  $isRangeSelection,
  $isTextNode,
  $setSelection,
  $setSlot,
  COMMAND_PRIORITY_BEFORE_EDITOR,
  COMMAND_PRIORITY_EDITOR,
  configExtension,
  createCommand,
  defineExtension,
  isModifierMatch,
  KEY_ARROW_LEFT_COMMAND,
  KEY_ARROW_RIGHT_COMMAND,
  KEY_TAB_COMMAND,
  type LexicalCommand,
  type LexicalNode,
  mergeRegister,
  type NodeKey,
  type PointType,
} from "lexical";

import { NodeSelectionDataSelectedExtension } from "@lexical/extension";
import {
  CoreImportExtension,
  defineImportRule,
  DOMImportExtension,
  domOverride,
  DOMRenderExtension,
  sel,
} from "@lexical/html";

import {
  $appendInline,
  $insertSlotHostAtRoot,
  $isSlotHostTextEmpty,
  registerHostChromeSelection,
  registerSlotHostArrowEscape,
  registerSlotHostBackspace,
} from "@/components/editor/extensions/slot-host";
import {
  $createCardNode,
  $isCardNode,
  CardNode,
} from "@/components/editor/nodes/card-node";

export const INSERT_CARD_COMMAND: LexicalCommand<void> = createCommand(
  "INSERT_CARD_COMMAND",
);

function $handleCardArrow(
  event: KeyboardEvent | null,
  isBackward: boolean,
): boolean {
  const selection = $getSelection();
  if (
    !$isRangeSelection(selection) ||
    (event !== null && !isModifierMatch(event, {}))
  ) {
    return false;
  }
  const adjacent = $getAdjacentNode(selection.focus, isBackward);
  if (!$isCardNode(adjacent)) {
    return false;
  }
  event?.preventDefault();
  const ns = $createNodeSelection();
  ns.add(adjacent.getKey());
  $setSelection(ns);
  return true;
}

function $findCardSlotContext(
  start: LexicalNode,
):
  | { card: CardNode; in: "title"; slotValue: LexicalNode }
  | { card: CardNode; in: "body" }
  | null {
  let cursor: LexicalNode | null = start;
  while (cursor !== null) {
    const slotName = $getSlotNameWithinHost(cursor);
    if (slotName === "title") {
      const host = $getSlotHost(cursor);
      if ($isCardNode(host)) {
        return { card: host, in: "title", slotValue: cursor };
      }
    }
    const parent: LexicalNode | null = cursor.getParent();
    if ($isCardNode(parent)) {
      return { card: parent, in: "body" };
    }
    cursor = parent ?? $getSlotHost(cursor);
  }
  return null;
}

function $isAtBlockEnd(point: PointType, block: LexicalNode): boolean {
  if (!$isElementNode(block)) {
    return false;
  }
  const last = block.getLastDescendant();
  if (last === null) {
    return point.key === block.getKey() && point.offset === 0;
  }
  if ($isTextNode(last)) {
    return (
      point.key === last.getKey() && point.offset === last.getTextContentSize()
    );
  }
  return false;
}

function $isAtBlockStart(point: PointType, block: LexicalNode): boolean {
  if (!$isElementNode(block)) {
    return false;
  }
  const first = block.getFirstDescendant();
  if (first === null) {
    return point.key === block.getKey() && point.offset === 0;
  }
  if ($isTextNode(first)) {
    return point.key === first.getKey() && point.offset === 0;
  }
  return false;
}

function $handleCardTab(
  event: KeyboardEvent | null,
  isBackward: boolean,
): boolean {
  const selection = $getSelection();
  if (!$isRangeSelection(selection) || !selection.isCollapsed()) {
    return false;
  }
  const context = $findCardSlotContext(selection.anchor.getNode());
  if (context === null) {
    return false;
  }
  if (!isBackward && context.in === "title") {
    const titleBlock = context.slotValue;
    if (
      !$isElementNode(titleBlock) ||
      !$isAtBlockEnd(selection.anchor, titleBlock)
    ) {
      return false;
    }
    const bodyFirst = context.card.getFirstChild();
    if ($isElementNode(bodyFirst)) {
      event?.preventDefault();
      bodyFirst.selectStart();
      return true;
    }
    event?.preventDefault();
    const bodyParagraph = $createParagraphNode();
    if (bodyFirst === null) {
      context.card.append(bodyParagraph);
    } else {
      bodyFirst.insertBefore(bodyParagraph);
    }
    bodyParagraph.select();
    return true;
  } else if (isBackward && context.in === "body") {
    const bodyFirst = context.card.getFirstChild();
    if (bodyFirst === null || !$isAtBlockStart(selection.anchor, bodyFirst)) {
      return false;
    }
    const titleSlot = $getSlot(context.card, "title");
    if ($isElementNode(titleSlot)) {
      event?.preventDefault();
      titleSlot.selectEnd();
      return true;
    }
  }
  return false;
}

const CardImportRule = defineImportRule({
  $import: (ctx, el) => {
    const card = $createCardNode().clear();
    const prevTitle = $getSlot(card, "title");
    const title = $isParagraphNode(prevTitle)
      ? prevTitle.clear()
      : $createParagraphNode();
    $setSlot(card, "title", title);
    for (const domChild of Array.from(el.children)) {
      const slotName = domChild.getAttribute("data-lexical-slot");
      if (slotName === "title") {
        $appendInline(title, ctx.$importChildren(domChild));
      } else {
        card.splice(card.getChildrenSize(), 0, ctx.$importOne(domChild));
      }
    }
    return [card];
  },
  match: sel.tag("div").attr("data-lexical-card", true),
  name: "@shadcn-editor/editor/card",
});

export const CardExtension = defineExtension({
  name: "@shadcn-editor/editor/Card",
  nodes: () => [CardNode],
  dependencies: [
    configExtension(NodeSelectionDataSelectedExtension, {
      nodes: [CardNode],
    }),
    configExtension(DOMRenderExtension, {
      overrides: [
        domOverride([CardNode], {
          $getSlotTargetElement: (_node, _slotName, hostDom) => hostDom,
        }),
      ],
    }),
    CoreImportExtension,
    configExtension(DOMImportExtension, {
      rules: [CardImportRule],
    }),
  ],
  register: (editor) => {
    return mergeRegister(
      editor.registerCommand(
        INSERT_CARD_COMMAND,
        () => {
          $insertSlotHostAtRoot($createCardNode());
          return true;
        },
        COMMAND_PRIORITY_EDITOR,
      ),
      editor.registerCommand(
        KEY_ARROW_RIGHT_COMMAND,
        (event) => $handleCardArrow(event, false),
        COMMAND_PRIORITY_BEFORE_EDITOR,
      ),
      editor.registerCommand(
        KEY_ARROW_LEFT_COMMAND,
        (event) => $handleCardArrow(event, true),
        COMMAND_PRIORITY_BEFORE_EDITOR,
      ),
      editor.registerCommand(
        KEY_TAB_COMMAND,
        (event) => $handleCardTab(event, event.shiftKey),
        COMMAND_PRIORITY_BEFORE_EDITOR,
      ),
      registerHostChromeSelection(editor, $isCardNode),
      registerSlotHostArrowEscape(editor, $isCardNode),
      registerSlotHostBackspace(editor, $isCardNode, $isSlotHostTextEmpty),
      (() => {
        let prevCardKey: NodeKey | null = null;
        let prevSlot: "title" | "body" | null = null;
        return editor.registerUpdateListener(({ editorState }) => {
          let activeCardKey: NodeKey | null = null;
          let activeSlot: "title" | "body" | null = null;
          editorState.read(() => {
            const selection = $getSelection();
            if ($isRangeSelection(selection)) {
              const context = $findCardSlotContext(selection.anchor.getNode());
              if (context !== null) {
                activeCardKey = context.card.getKey();
                activeSlot = context.in;
              }
            }
          });
          if (prevCardKey === activeCardKey && prevSlot === activeSlot) {
            return;
          }
          if (prevCardKey !== null && prevCardKey !== activeCardKey) {
            const dom = editor.getElementByKey(prevCardKey);
            if (dom !== null) {
              dom.removeAttribute("data-current-slot");
            }
          }
          if (activeCardKey !== null && activeSlot !== null) {
            const dom = editor.getElementByKey(activeCardKey);
            if (dom !== null) {
              dom.setAttribute("data-current-slot", activeSlot);
            }
          }
          prevCardKey = activeCardKey;
          prevSlot = activeSlot;
        });
      })(),
    );
  },
});

import {
  $getRoot,
  $getSelection,
  $isRangeSelection,
  $nodesOfType,
  configExtension,
  defineExtension,
  type LexicalEditor,
} from "lexical";

import {
  $createCodeNode,
  $isCodeNode,
  CodeIndentExtension,
  CodeNode,
} from "@lexical/code-core";
import {
  CodeShikiExtension,
  ShikiTokenizer,
  type Tokenizer,
} from "@lexical/code-shiki";
import { $setBlocksType } from "@lexical/selection";

export function insertCodeBlock(editor: LexicalEditor) {
  editor.update(() => {
    const selection = $getSelection() ?? $getRoot().selectEnd();
    if (!$isRangeSelection(selection)) {
      return;
    }

    if ($isCodeNode(selection.anchor.getNode().getTopLevelElement())) {
      return;
    }

    if (selection.isCollapsed()) {
      $setBlocksType(selection, () => $createCodeNode());
      return;
    }

    const textContent = selection.getTextContent();
    const codeNode = $createCodeNode();
    selection.insertNodes([codeNode]);

    const updatedSelection = $getSelection();
    if ($isRangeSelection(updatedSelection)) {
      updatedSelection.insertRawText(textContent);
    }
  });
}

const LIGHT_CODE_THEME = "github-light";
const DARK_CODE_THEME = "github-dark";

function getPreferredCodeTheme() {
  if (typeof document === "undefined") {
    return LIGHT_CODE_THEME;
  }
  return document.documentElement.classList.contains("dark")
    ? DARK_CODE_THEME
    : LIGHT_CODE_THEME;
}

const tokenizer: Tokenizer = {
  ...ShikiTokenizer,
  defaultTheme: getPreferredCodeTheme(),
};

export const CodeExtension = defineExtension({
  name: "@shadcn-editor/editor/Code",
  dependencies: [
    configExtension(CodeShikiExtension, { tokenizer }),
    configExtension(CodeIndentExtension, {
      tabSize: 2,
      escapeWithArrows: true,
    }),
  ],
  register: (editor) => {
    const syncCodeTheme = () => {
      const theme = getPreferredCodeTheme();
      editor.update(() => {
        for (const codeNode of $nodesOfType(CodeNode)) {
          if (codeNode.getTheme() !== theme) {
            codeNode.setTheme(theme);
          }
        }
      });
    };

    const observer = new MutationObserver(syncCodeTheme);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    return () => observer.disconnect();
  },
});

