import { Loader2 } from "lucide-react";

const WIDGET_SCRIPT_URL = "https://platform.twitter.com/widgets.js";

type TwitterWindow = Window & {
  twttr?: {
    widgets: {
      createTweet: (
        tweetID: string,
        container: HTMLElement | null,
      ) => Promise<unknown>;
    };
  };
};

type TweetComponentProps = Readonly<{
  className: Readonly<{
    base: string;
    focus: string;
  }>;
  format: ElementFormatType | null;
  nodeKey: NodeKey;
  onError?: (error: string) => void;
  onLoad?: () => void;
  tweetID: string;
}>;

let isTwitterScriptLoading = true;

function TweetComponent({
  className,
  format,
  nodeKey,
  onError,
  onLoad,
  tweetID,
}: TweetComponentProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const previousTweetIDRef = useRef<string>("");
  const [isTweetLoading, setIsTweetLoading] = useState(false);

  const createTweet = useCallback(async () => {
    try {
      await (window as TwitterWindow).twttr?.widgets.createTweet(
        tweetID,
        containerRef.current,
      );
      setIsTweetLoading(false);
      isTwitterScriptLoading = false;
      if (onLoad) {
        onLoad();
      }
    } catch (error) {
      if (onError) {
        onError(String(error));
      }
    }
  }, [onError, onLoad, tweetID]);

  useEffect(() => {
    if (tweetID !== previousTweetIDRef.current) {
      setIsTweetLoading(true);

      if (isTwitterScriptLoading) {
        const doc = containerRef.current?.ownerDocument ?? document;
        const script = doc.createElement("script");
        script.src = WIDGET_SCRIPT_URL;
        script.async = true;
        doc.body?.appendChild(script);
        script.onload = createTweet;
        if (onError) {
          script.onerror = onError as OnErrorEventHandler;
        }
      } else {
        createTweet().catch(console.error);
      }

      previousTweetIDRef.current = tweetID;
    }
  }, [createTweet, onError, tweetID]);

  return (
    <BlockWithAlignableContents
      className={className}
      format={format}
      nodeKey={nodeKey}
    >
      {isTweetLoading ? (
        <div className="flex h-32 w-full max-w-xl items-center justify-center rounded-md border bg-muted">
          <Loader2 className="size-5 animate-spin text-muted-foreground" />
        </div>
      ) : null}
      <div
        ref={containerRef}
        className="inline-block w-full max-w-xl align-top"
      />
    </BlockWithAlignableContents>
  );
}

export type SerializedTweetNode = Spread<
  {
    id: string;
  },
  SerializedDecoratorBlockNode
>;

export class TweetNode extends DecoratorBlockNode {
  __id: string;

  $config() {
    return this.config("tweet", { extends: DecoratorBlockNode });
  }

  static clone(node: TweetNode): TweetNode {
    return new TweetNode(node.__id, node.__format, node.__key);
  }

  static importJSON(serializedNode: SerializedTweetNode): TweetNode {
    return $createTweetNode(serializedNode.id).updateFromJSON(serializedNode);
  }

  exportJSON(): SerializedTweetNode {
    return {
      ...super.exportJSON(),
      id: this.getId(),
    };
  }

  exportDOM(): DOMExportOutput {
    const element = $getDocument().createElement("div");
    element.setAttribute("data-lexical-tweet-id", this.__id);
    const text = $getDocument().createTextNode(this.getTextContent());
    element.append(text);
    return { element };
  }

  constructor(id: string, format?: ElementFormatType, key?: NodeKey) {
    super(format, key);
    this.__id = id;
  }

  getId(): string {
    return this.getLatest().__id;
  }

  getTextContent(): string {
    return `https://x.com/i/web/status/${this.__id}`;
