export function parseFigmaDocumentID(url: string): string | null {
  const trimmed = url.trim();
  if (/^[0-9a-zA-Z]{22,128}$/.test(trimmed)) {
    return trimmed;
  }
  const match =
    /^https:\/\/([\w.-]+\.)?figma\.com\/(file|proto|design|board)\/([0-9a-zA-Z]{22,128})(?:\/.*)?$/.exec(
      trimmed,
    );
  return match?.[3] ?? null;
}

