import { useCallback, useEffect, useRef, useState } from "react";

import {
  $getNearestNodeFromDOMNode,
  $getNodeByKey,
  $getRoot,
  $getSelection,
  $isDecoratorNode,
  $isNodeSelection,
  COPY_COMMAND,
  CUT_COMMAND,
  PASTE_COMMAND,
  registerEventListener,
} from "lexical";

import { $isAutoLinkNode, $isLinkNode } from "@lexical/link";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";

import {
  Clipboard,
  ClipboardType,
  Copy,
  Link2Off,
  Scissors,
  Trash2,
} from "lucide-react";

import { useTranslation } from "@/components/editor/plugins/i18n-plugin";
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "@/components/ui/context-menu";

export function ContextMenuPlugin() {
  const [editor] = useLexicalComposerContext();
  const { t, dir } = useTranslation();
  const triggerRef = useRef<HTMLDivElement>(null);
  const [target, setTarget] = useState<{ key: string; isLink: boolean } | null>(
    null,
  );

  useEffect(() => {
    function onContextMenu(event: MouseEvent) {
      const trigger = triggerRef.current;
      if (trigger === null || !(event.target instanceof Node)) {
        return;
      }
      event.preventDefault();
      editor.read(() => {
        const node =
          $getNearestNodeFromDOMNode(event.target as Node) ?? $getRoot();
        setTarget({
          key: node.getKey(),
          isLink: $isLinkNode(node) || $isLinkNode(node.getParent()),
        });
      });
      trigger.dispatchEvent(
        new MouseEvent("contextmenu", {
          bubbles: true,
          cancelable: true,
          clientX: event.clientX,
          clientY: event.clientY,
        }),
      );
    }

    return editor.registerRootListener((rootElement) => {
      if (rootElement !== null) {
        return registerEventListener(rootElement, "contextmenu", onContextMenu);
      }
    });
  }, [editor]);

  const removeLink = useCallback(() => {
    if (target === null) {
      return;
    }
    editor.update(() => {
      const node = $getNodeByKey(target.key);
      const parent = node?.getParent();
      const link = $isLinkNode(node)
        ? node
        : $isLinkNode(parent)
          ? parent
          : null;
      if (link === null) {
        return;
      }
      if ($isAutoLinkNode(link)) {
        link.setIsUnlinked(true);
        return;
      }
      for (const child of link.getChildren()) {
        link.insertBefore(child);
      }
      link.remove();
    });
  }, [editor, target]);

  const pasteFromClipboard = useCallback(
    async (plainText: boolean) => {
      try {
        const data = new DataTransfer();
        if (plainText) {
          data.setData("text/plain", await navigator.clipboard.readText());
        } else {
          const [item] = await navigator.clipboard.read();
          for (const type of item.types) {
            data.setData(type, await (await item.getType(type)).text());
          }
        }
        editor.dispatchCommand(
          PASTE_COMMAND,
          new ClipboardEvent("paste", { clipboardData: data }),
        );
      } catch {
        window.alert(t.clipboardNotAllowed);
      }
    },
    [editor, t],
  );

  const deleteNode = useCallback(() => {
    editor.update(() => {
      const selection = $getSelection();
      if ($isNodeSelection(selection)) {
        for (const node of selection.getNodes()) {
          if ($isDecoratorNode(node)) {
            node.remove();
          }
        }
        return;
      }
      const node = target === null ? null : $getNodeByKey(target.key);
      if (node === null) {
        return;
      }
      if ($isDecoratorNode(node)) {
        node.remove();
      } else {
        node.getTopLevelElement()?.remove();
      }
    });
  }, [editor, target]);

  return (
    <ContextMenu>
      <ContextMenuTrigger ref={triggerRef} className="hidden" />
      <ContextMenuContent dir={dir} className="w-52">
        {target?.isLink && (
          <>
            <ContextMenuItem onClick={removeLink}>
              <Link2Off />
              {t.removeLink}
            </ContextMenuItem>
            <ContextMenuSeparator />
          </>
        )}
        <ContextMenuItem
          onClick={() => editor.dispatchCommand(CUT_COMMAND, null)}
        >
          <Scissors />
          {t.cut}
        </ContextMenuItem>
        <ContextMenuItem
          onClick={() => editor.dispatchCommand(COPY_COMMAND, null)}
        >
          <Copy />
          {t.copy}
        </ContextMenuItem>
        <ContextMenuItem onClick={() => pasteFromClipboard(false)}>
          <Clipboard />
          {t.paste}
        </ContextMenuItem>
        <ContextMenuItem onClick={() => pasteFromClipboard(true)}>
          <ClipboardType />
          {t.pasteAsPlainText}
        </ContextMenuItem>
        <ContextMenuSeparator />
        <ContextMenuItem variant="destructive" onClick={deleteNode}>
          <Trash2 />
          {t.deleteNode}
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  );
}

import { useEffect, useRef, useState } from "react";

import {
  $createParagraphNode,
  $createTextNode,
  $getNearestNodeFromDOMNode,
  $isElementNode,
} from "lexical";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { DraggableBlockPlugin_EXPERIMENTAL } from "@lexical/react/LexicalDraggableBlockPlugin";

import { GripVertical, Plus } from "lucide-react";

import { useLanguage } from "@/components/editor/plugins/i18n-plugin";
import { cn } from "@/lib/utils";

const DRAGGABLE_BLOCK_MENU_CLASSNAME = "draggable-block-menu";

function isOnMenu(element: HTMLElement): boolean {
  return !!element.closest(`.${DRAGGABLE_BLOCK_MENU_CLASSNAME}`);
}

export function DraggableBlockPlugin() {
  const [editor] = useLexicalComposerContext();
  const { dir } = useLanguage();
  const menuRef = useRef<HTMLDivElement>(null);
  const targetLineRef = useRef<HTMLDivElement>(null);
  const [draggableElement, setDraggableElement] = useState<HTMLElement | null>(
    null,
  );
  const [anchorElem, setAnchorElem] = useState<HTMLElement | null>(null);

  useEffect(() => {
    return editor.registerRootListener((rootElement) => {
      setAnchorElem(rootElement?.parentElement ?? null);
    });
  }, [editor]);

  if (!anchorElem) {
    return null;
  }

  function insertSlashBlock(event: React.MouseEvent) {
    if (!draggableElement) {
      return;
    }
    editor.update(() => {
      const node = $getNearestNodeFromDOMNode(draggableElement);
      if (!node) {
        return;
      }
      if ($isElementNode(node)) {
        const textContent = node.getTextContent();
        const needsSpace = textContent !== "" && !/\s$/.test(textContent);
        node.selectEnd().insertText(needsSpace ? " /" : "/");
        return;
      }
      const paragraph = $createParagraphNode();
      const textNode = $createTextNode("/");
      paragraph.append(textNode);
      if (event.altKey || event.ctrlKey) {
        node.insertBefore(paragraph);
      } else {
        node.insertAfter(paragraph);
      }
      textNode.selectEnd();
    });
    editor.focus();
  }

  return (
    <DraggableBlockPlugin_EXPERIMENTAL
      anchorElem={anchorElem}
      menuRef={menuRef}
      targetLineRef={targetLineRef}
      menuComponent={
        <div
          ref={menuRef}
          className={cn(
            DRAGGABLE_BLOCK_MENU_CLASSNAME,
            "absolute top-0 flex cursor-grab items-center rounded-md p-px opacity-0 will-change-transform active:cursor-grabbing",
            dir === "rtl" ? "right-2" : "left-0",
          )}
        >
          <button
            type="button"
            title="Click to open block menu"
            className="flex size-5 items-center justify-center rounded-sm text-muted-foreground hover:bg-accent hover:text-accent-foreground"
            onMouseDown={(event) => event.preventDefault()}
            onClick={insertSlashBlock}
          >
            <Plus className="size-4" />
          </button>
          <div className="flex size-5 items-center justify-center rounded-sm text-muted-foreground hover:bg-accent hover:text-accent-foreground">
            <GripVertical className="size-4" />
          </div>
        </div>
      }
      targetLineComponent={
        <div
          ref={targetLineRef}
          className="pointer-events-none absolute top-0 left-0 h-1 rounded-full bg-primary/50 opacity-0 will-change-transform"
        />
      }
      isOnMenu={isOnMenu}
      onElementChanged={setDraggableElement}
    />
  );
}

import { useCallback, useMemo, useState } from "react";

import type { TextNode } from "lexical";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import {
  LexicalTypeaheadMenuPlugin,
  MenuOption,
  useBasicTypeaheadTriggerMatch,
} from "@lexical/react/LexicalTypeaheadMenuPlugin";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import compactEmojis from "emojibase-data/en/compact.json";

import {
  $createEmojiNode,
  EMOJI_CLASS_NAME,
} from "@/components/editor/nodes/emoji-node";
import { useLanguage } from "@/components/editor/plugins/i18n-plugin";
import { Command, CommandItem, CommandList } from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

const MAX_SUGGESTIONS = 8;

const EXCLUDED_GROUPS = new Set([2]);

type EmojiEntry = {
  emoji: string;
  name: string;
  keywords: string[];
  hexcode: string;
};

const EMOJI_ENTRIES: EmojiEntry[] = compactEmojis
  .filter(
    (entry) => entry.group !== undefined && !EXCLUDED_GROUPS.has(entry.group),
  )
  .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
  .map((entry) => ({
    emoji: entry.unicode,
    name: entry.label
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, ""),
    keywords: entry.tags ?? [],
    hexcode: entry.hexcode,
  }));

function normalize(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, "");
}

function searchEmojis(query: string): EmojiEntry[] {
  const q = normalize(query);
  if (!q) {
    return [];
  }

  const startsWith: EmojiEntry[] = [];
  const includes: EmojiEntry[] = [];

  for (const entry of EMOJI_ENTRIES) {
    const name = normalize(entry.name);
    if (name.startsWith(q)) {
      startsWith.push(entry);
      continue;
    }
    const keywordMatch = entry.keywords.some((keyword) =>
      normalize(keyword).startsWith(q),
    );
    if (keywordMatch) {
      startsWith.push(entry);
      continue;
    }
    if (
      name.includes(q) ||
      entry.keywords.some((keyword) => normalize(keyword).includes(q))
    ) {
      includes.push(entry);
    }
  }

  return [...startsWith, ...includes];
}

class EmojiTypeaheadOption extends MenuOption {
  entry: EmojiEntry;

  constructor(entry: EmojiEntry) {
    super(entry.hexcode);
    this.entry = entry;
  }
}

export function EmojiPickerPlugin() {
  const [editor] = useLexicalComposerContext();
  const { dir } = useLanguage();
  const [queryString, setQueryString] = useState<string | null>(null);

  const checkForTriggerMatch = useBasicTypeaheadTriggerMatch(":", {
    minLength: 0,
  });

  const options = useMemo(() => {
    if (queryString === null) {
      return [];
    }
    const matches =
      queryString === "" ? EMOJI_ENTRIES : searchEmojis(queryString);
    return matches
      .slice(0, MAX_SUGGESTIONS)
      .map((entry) => new EmojiTypeaheadOption(entry));
  }, [queryString]);

  const onSelectOption = useCallback(
    (
      option: EmojiTypeaheadOption,
      nodeToReplace: TextNode | null,
      closeMenu: () => void,
    ) => {
      editor.update(() => {
        const emojiNode = $createEmojiNode(
          EMOJI_CLASS_NAME,
          option.entry.emoji,
        );
        if (nodeToReplace) {
          nodeToReplace.replace(emojiNode);
        }
        emojiNode.selectNext();
        closeMenu();
      });
    },
    [editor],
  );

  return (
    <LexicalTypeaheadMenuPlugin<EmojiTypeaheadOption>
      onQueryChange={setQueryString}
      onSelectOption={onSelectOption}
      triggerFn={checkForTriggerMatch}
      options={options}
      menuRenderFn={(
        anchorElementRef,
        { selectedIndex, selectOptionAndCleanUp, setHighlightedIndex },
      ) =>
        anchorElementRef.current && options.length > 0 ? (
          <Popover open>
            <PopoverPrimitive.Portal
              dir={dir}
              container={anchorElementRef.current}
            >
              <PopoverTrigger
                nativeButton={false}
                render={
                  <span
                    aria-hidden
                    className="pointer-events-none absolute inset-x-0 top-0 h-0"
                  />
                }
              />
              <PopoverContent
                dir={dir}
                side="bottom"
                align="start"
                sideOffset={6}
                initialFocus={false}
                className="w-auto overflow-hidden p-0"
              >
                <Command
                  value={
                    selectedIndex === null
                      ? ""
                      : (options[selectedIndex]?.entry.hexcode ?? "")
                  }
                  onValueChange={(nextValue) => {
                    const index = options.findIndex(
                      (option) => option.entry.hexcode === nextValue,
                    );
                    if (index >= 0) {
                      setHighlightedIndex(index);
                    }
                  }}
                  shouldFilter={false}
                >
                  <CommandList className="max-h-64 w-56">
                    {options.map((option) => (
                      <CommandItem
                        key={option.key}
                        ref={option.setRefElement}
                        value={option.entry.hexcode}
                        onSelect={() => selectOptionAndCleanUp(option)}
                      >
                        <span className="text-base leading-none">
                          {option.entry.emoji}
                        </span>
                        <span className="truncate text-muted-foreground">
                          :{option.entry.name}:
                        </span>
                      </CommandItem>
                    ))}
                  </CommandList>
                </Command>
              </PopoverContent>
            </PopoverPrimitive.Portal>
          </Popover>
        ) : null
      }
    />
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import {
  $getNodeByKey,
  $getSelection,
  $isRangeSelection,
  type LexicalEditor,
  type RangeSelection,
  registerEventListener,
} from "lexical";

import { $isMarkNode, $wrapSelectionInMarkNode } from "@lexical/mark";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useExtensionDependency } from "@lexical/react/useExtensionComponent";
import { useExtensionSignalValue } from "@lexical/react/useExtensionSignalValue";
