function CommentRow({
  comment,
  thread,
  state,
  rtf,
  now,
}: {
  comment: Comment;
  thread: Thread;
  state: CommentState;
  rtf: Intl.RelativeTimeFormat;
  now: number;
}) {
  const { t } = useTranslation();
  const minutes = Math.round((comment.timeStamp - now) / 60000);

  return (
    <div className="group/comment">
      <div className="flex items-center gap-1 text-xs">
        <span className="font-medium">{comment.author}</span>
        <span className="text-muted-foreground">
          {minutes > -1 ? t.justNow : rtf.format(minutes, "minute")}
        </span>
        {!comment.deleted && (
          <DeleteButton
            title={t.deleteCommentConfirm}
            className="ms-auto opacity-0 group-hover/comment:opacity-100"
            onDelete={() => {
              const info = deleteCommentOrThread(state, comment, thread);
              if (info !== null) {
                addComment(state, info.markedComment, thread, info.index);
              }
            }}
          />
        )}
      </div>
      {comment.deleted ? (
        <p className="text-xs text-muted-foreground italic">
          {t.deletedComment}
        </p>
      ) : (
        <p className="text-sm break-words">{comment.content}</p>
      )}
    </div>
  );
}

function ReplyComposer({
  thread,
  state,
}: {
  thread: Thread;
  state: CommentState;
}) {
  const { t } = useTranslation();
  const [content, setContent] = useState("");

  const submit = () => {
    const text = content.trim();
    if (text === "") {
      return;
    }
    addComment(state, createComment(text, t.you), thread);
    setContent("");
  };

  return (
    <InputGroup
      className="mt-2 h-8 rounded-md"
      onClick={(event) => event.stopPropagation()}
    >
      <InputGroupInput
        value={content}
        placeholder={t.replyToComment}
        className="text-xs"
        onChange={(event) => setContent(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === "Enter") {
            event.preventDefault();
            submit();
          }
        }}
      />
      <InputGroupAddon align="inline-end">
        <InputGroupButton
          size="icon-xs"
          aria-label={t.comment}
          disabled={content.trim() === ""}
          onClick={submit}
        >
          <SendHorizontal className="rtl:rotate-180" />
        </InputGroupButton>
      </InputGroupAddon>
    </InputGroup>
  );
}

function ThreadCard({
  editor,
  thread,
  state,
  active,
  rtf,
  now,
}: {
  editor: LexicalEditor;
  thread: Thread;
  state: CommentState;
  active: boolean;
  rtf: Intl.RelativeTimeFormat;
  now: number;
}) {
  const { t } = useTranslation();

  const handleClickThread = () => {
    const markNodeKeys = state.markNodeMap.get(thread.id);
    if (markNodeKeys === undefined || active) {
      return;
    }
    const activeElement = document.activeElement;
    const markNodeKey = Array.from(markNodeKeys)[0];
    editor.update(
      () => {
        const markNode = $getNodeByKey(markNodeKey);
        if ($isMarkNode(markNode)) {
          markNode.selectStart();
        }
      },
      {
        onUpdate() {
          const markElem = editor.getElementByKey(markNodeKey);
          const scroller = getScrollParent(editor.getRootElement());
          if (markElem !== null && scroller !== null) {
            const markRect = markElem.getBoundingClientRect();
            const scrollerRect = scroller.getBoundingClientRect();
            if (
              markRect.top < scrollerRect.top ||
              markRect.bottom > scrollerRect.bottom
            ) {
              scroller.scrollTo({
                behavior: "smooth",
                top:
                  markRect.top -
                  scrollerRect.top +
                  scroller.scrollTop -
                  scroller.clientHeight / 2,
              });
            }
          }
          if (activeElement !== null) {
            (activeElement as HTMLElement).focus();
          }
        },
      },
    );
  };

  return (
    <div
      onClick={handleClickThread}
      className={cn(
        "rounded-md border bg-background p-2 text-start",
        state.markNodeMap.has(thread.id) && "cursor-pointer",
        active && "border-ring ring-1 ring-ring",
      )}
    >
      <div className="flex items-start justify-between gap-1">
        <blockquote className="line-clamp-2 border-s-2 ps-2 text-xs text-muted-foreground italic">
          {thread.quote}
        </blockquote>
        <DeleteButton
          title={t.deleteThreadConfirm}
          className="-mt-0.5 shrink-0"
          onDelete={() => {
            deleteCommentOrThread(state, thread);
            removeThreadMarks(editor, state, thread.id);
          }}
        />
      </div>
      <div className="mt-2 flex flex-col gap-2">
        {thread.comments.map((comment) => (
          <CommentRow
            key={comment.id}
            comment={comment}
            thread={thread}
            state={state}
            rtf={rtf}
            now={now}
          />
        ))}
      </div>
      <ReplyComposer thread={thread} state={state} />
    </div>
  );
}

export function CommentsPanel() {
  const [editor] = useLexicalComposerContext();
  const { t, language } = useTranslation();
  const state = useExtensionDependency(CommentExtension).output;
  const comments = useExtensionSignalValue(CommentExtension, "comments");
  const activeIDs = useExtensionSignalValue(CommentExtension, "activeIDs");
  const [now, setNow] = useState(() => Date.now());

  const rtf = useMemo(
    () =>
      new Intl.RelativeTimeFormat(language, {
        numeric: "auto",
        style: "short",
      }),
    [language],
  );

  useEffect(() => {
    const id = setInterval(() => {
      setNow(Date.now());
    }, 10000);
    return () => clearInterval(id);
  }, []);

  return (
    <SidebarGroup>
      <SidebarGroupLabel>{t.comments}</SidebarGroupLabel>
      <SidebarGroupContent className="px-2">
        {comments.length === 0 ? (
          <p className="py-4 text-center text-xs text-muted-foreground">
            {t.noComments}
          </p>
        ) : (
          <div className="flex flex-col gap-2">
            {comments.map((commentOrThread) =>
              commentOrThread.type === "thread" ? (
                <ThreadCard
                  key={commentOrThread.id}
                  editor={editor}
                  thread={commentOrThread}
                  state={state}
                  active={activeIDs.includes(commentOrThread.id)}
                  rtf={rtf}
                  now={now}
                />
              ) : null,
            )}
          </div>
        )}
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

/* eslint-disable react-refresh/only-export-components */
import { useRef } from "react";

import { createPortal } from "react-dom";

import {
  configExtension,
  CONTROL_OR_META,
  defineExtension,
  isExactShortcutMatch,
} from "lexical";

import { ReactExtension } from "@lexical/react/ReactExtension";
import type { DecoratorComponentProps } from "@lexical/react/ReactPluginHostExtension";
import { useExtensionSignalValue } from "@lexical/react/useExtensionSignalValue";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";

import {
  CaseSensitive,
  ChevronDown,
  ChevronUp,
  Regex,
  Replace,
  ReplaceAll,
  X,
} from "lucide-react";

import {
  CLOSE_FIND_REPLACE_COMMAND,
  FIND_NEXT_COMMAND,
  FIND_PREV_COMMAND,
  FindReplaceExtension,
  REPLACE_ALL_COMMAND,
  REPLACE_CURRENT_COMMAND,
  SET_REPLACE_TERM_COMMAND,
  SET_SEARCH_TERM_COMMAND,
  TOGGLE_CASE_SENSITIVE_COMMAND,
  TOGGLE_REGEX_COMMAND,
} from "@/components/editor/extensions/find-replace";
import { useTranslation } from "@/components/editor/plugins/i18n-plugin";
import { Button } from "@/components/ui/button";
import { ButtonGroup } from "@/components/ui/button-group";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

function FindReplacePanel({ context }: DecoratorComponentProps) {
  const [editor] = context;
  const { t, dir } = useTranslation();
  const isEditable = useLexicalEditable();
  const isOpen = useExtensionSignalValue(FindReplaceExtension, "isOpen");
  const searchTerm = useExtensionSignalValue(
    FindReplaceExtension,
    "searchTerm",
  );
  const replaceTerm = useExtensionSignalValue(
    FindReplaceExtension,
    "replaceTerm",
  );
  const caseSensitive = useExtensionSignalValue(
    FindReplaceExtension,
    "caseSensitive",
  );
  const isRegex = useExtensionSignalValue(FindReplaceExtension, "isRegex");
  const matches = useExtensionSignalValue(FindReplaceExtension, "matches");
  const effectiveIndex = useExtensionSignalValue(
    FindReplaceExtension,
    "effectiveIndex",
  );
  const regexError = useExtensionSignalValue(
    FindReplaceExtension,
    "regexError",
  );
  const findInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) {
    return null;
  }

  const goToNext = () => editor.dispatchCommand(FIND_NEXT_COMMAND, undefined);
  const goToPrevious = () =>
    editor.dispatchCommand(FIND_PREV_COMMAND, undefined);
  const close = () => {
    editor.dispatchCommand(CLOSE_FIND_REPLACE_COMMAND, undefined);
    editor.focus();
  };

  const handlePanelKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "Escape") {
      event.preventDefault();
      close();
      return;
    }
    if (
      isExactShortcutMatch(event, "g", CONTROL_OR_META) ||
      isExactShortcutMatch(event, "g", { ...CONTROL_OR_META, shiftKey: true })
    ) {
      event.preventDefault();
      if (event.shiftKey) {
        goToPrevious();
      } else {
        goToNext();
      }
      return;
    }
    if (
      isExactShortcutMatch(event, "f", CONTROL_OR_META) ||
      isExactShortcutMatch(event, "f", { altKey: true, metaKey: true })
    ) {
      event.preventDefault();
      findInputRef.current?.focus();
    }
  };

  const canNavigate = matches.length > 0;
  const canReplace = isEditable && matches.length > 0;
  const statusLabel = regexError
    ? t.invalidRegex
    : searchTerm === ""
      ? null
      : matches.length === 0
        ? t.noResults
        : t.matchCount
            .replace("{current}", String(effectiveIndex + 1))
            .replace("{total}", String(matches.length));

  const rootElement = editor.getRootElement();
  const portalTarget =
    rootElement?.parentElement ?? rootElement?.ownerDocument.body ?? null;
  if (!portalTarget) {
    return null;
  }

  return createPortal(
    <div
      role="dialog"
      aria-label={t.findAndReplace}
      dir={dir}
      onKeyDown={handlePanelKeyDown}
      className="absolute end-2 top-2 z-50 flex w-80 flex-col gap-2 rounded-md border bg-popover p-2 text-popover-foreground shadow-md"
    >
      <div className="flex items-center justify-between gap-2">
        <span className="ps-1 text-sm font-medium">{t.findAndReplace}</span>
        <Tooltip>
          <TooltipTrigger
            render={
              <Button
                variant="ghost"
                size="icon-xs"
                aria-label={t.closeFindReplace}
                onClick={close}
              >
                <X />
              </Button>
            }
          />
          <TooltipContent>{t.closeFindReplace}</TooltipContent>
        </Tooltip>
      </div>
      <InputGroup>
        <InputGroupInput
          ref={findInputRef}
          autoFocus
          placeholder={t.find}
          aria-label={t.find}
          aria-invalid={regexError || undefined}
          value={searchTerm}
          onChange={(event) => {
            editor.dispatchCommand(SET_SEARCH_TERM_COMMAND, event.target.value);
          }}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              if (event.shiftKey) {
                goToPrevious();
              } else {
                goToNext();
              }
            }
          }}
        />
        <InputGroupAddon align="inline-end">
          <Tooltip>
            <TooltipTrigger
              render={
                <InputGroupButton
                  size="icon-xs"
                  aria-label={t.matchCase}
                  aria-pressed={caseSensitive}
                  className={cn(
                    caseSensitive && "bg-accent text-accent-foreground",
                  )}
                  onClick={() => {
                    editor.dispatchCommand(
                      TOGGLE_CASE_SENSITIVE_COMMAND,
                      undefined,
                    );
                  }}
                >
                  <CaseSensitive />
                </InputGroupButton>
              }
            />
            <TooltipContent>{t.matchCase}</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger
              render={
                <InputGroupButton
                  size="icon-xs"
                  aria-label={t.useRegex}
                  aria-pressed={isRegex}
                  className={cn(isRegex && "bg-accent text-accent-foreground")}
                  onClick={() => {
                    editor.dispatchCommand(TOGGLE_REGEX_COMMAND, undefined);
                  }}
                >
                  <Regex />
                </InputGroupButton>
              }
            />
            <TooltipContent>{t.useRegex}</TooltipContent>
          </Tooltip>
        </InputGroupAddon>
      </InputGroup>
      <InputGroup>
        <InputGroupInput
          placeholder={t.replace}
          aria-label={t.replace}
          disabled={!isEditable}
          value={replaceTerm}
          onChange={(event) => {
            editor.dispatchCommand(
              SET_REPLACE_TERM_COMMAND,
              event.target.value,
            );
          }}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              editor.dispatchCommand(REPLACE_CURRENT_COMMAND, undefined);
            }
          }}
        />
        <InputGroupAddon align="inline-end">
          <Tooltip>
            <TooltipTrigger
              render={
                <InputGroupButton
                  size="icon-xs"
                  aria-label={t.replace}
                  disabled={!canReplace}
                  onClick={() => {
                    editor.dispatchCommand(REPLACE_CURRENT_COMMAND, undefined);
                  }}
                >
                  <Replace className="rtl:-scale-x-100" />
                </InputGroupButton>
              }
            />
            <TooltipContent>{t.replace}</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger
              render={
                <InputGroupButton
                  size="icon-xs"
                  aria-label={t.replaceAll}
                  disabled={!canReplace}
                  onClick={() => {
                    editor.dispatchCommand(REPLACE_ALL_COMMAND, undefined);
                  }}
                >
                  <ReplaceAll className="rtl:-scale-x-100" />
                </InputGroupButton>
              }
            />
            <TooltipContent>{t.replaceAll}</TooltipContent>
          </Tooltip>
        </InputGroupAddon>
      </InputGroup>
      <div className="flex items-center justify-between gap-2">
        <span
          aria-live="polite"
          className={cn(
            "ps-1 text-xs whitespace-nowrap tabular-nums",
            regexError ? "text-destructive" : "text-muted-foreground",
          )}
