        <ButtonGroup>
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="outline"
                  size="icon-sm"
                  aria-label={t.previousMatch}
                  disabled={!canNavigate}
                  onClick={goToPrevious}
                >
                  <ChevronUp />
                </Button>
              }
            />
            <TooltipContent>{t.previousMatch}</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="outline"
                  size="icon-sm"
                  aria-label={t.nextMatch}
                  disabled={!canNavigate}
                  onClick={goToNext}
                >
                  <ChevronDown />
                </Button>
              }
            />
            <TooltipContent>{t.nextMatch}</TooltipContent>
          </Tooltip>
        </ButtonGroup>
      </div>
    </div>,
    portalTarget,
  );
}

