const mentionsCache = new Map<string, string[] | null>();

const lookupService = {
  search(query: string, callback: (results: string[]) => void): void {
    setTimeout(() => {
      const results = MENTIONS.filter((mention) =>
        mention.toLowerCase().includes(query.toLowerCase()),
      );
      callback(results);
    }, 250);
  },
};

function useMentionLookupService(mentionString: string | null) {
  const [results, setResults] = useState<string[]>([]);

  useEffect(() => {
    if (mentionString === null) {
      setResults([]);
      return;
    }

    const cachedResults = mentionsCache.get(mentionString);
    if (cachedResults === null) {
      return;
    }
    if (cachedResults !== undefined) {
      setResults(cachedResults);
      return;
    }

    mentionsCache.set(mentionString, null);
    lookupService.search(mentionString, (newResults) => {
      mentionsCache.set(mentionString, newResults);
      setResults(newResults);
    });
  }, [mentionString]);

  return results;
}

function checkForAtSignMentions(
  text: string,
  minMatchLength: number,
): MenuTextMatch | null {
  let match = AtSignMentionsRegex.exec(text);

  if (match === null) {
    match = AtSignMentionsRegexAliasRegex.exec(text);
  }
  if (match !== null) {
    const maybeLeadingWhitespace = match[1];
    const matchingString = match[3];
    if (matchingString.length >= minMatchLength) {
      return {
        leadOffset: match.index + maybeLeadingWhitespace.length,
        matchingString,
        replaceableString: match[2],
      };
    }
  }
  return null;
}

class MentionTypeaheadOption extends MenuOption {
  name: string;

  constructor(name: string) {
    super(name);
    this.name = name;
  }
}

export function MentionPlugin() {
  const [editor] = useLexicalComposerContext();
  const { dir } = useLanguage();
  const [queryString, setQueryString] = useState<string | null>(null);

  const results = useMentionLookupService(queryString);

  const options = useMemo(
    () =>
      results
        .slice(0, MAX_SUGGESTIONS)
        .map((result) => new MentionTypeaheadOption(result)),
    [results],
  );

  const onSelectOption = useCallback(
    (
      option: MentionTypeaheadOption,
      nodeToReplace: TextNode | null,
      closeMenu: () => void,
    ) => {
      editor.update(() => {
        const mentionNode = $createMentionNode(option.name);
        if (nodeToReplace) {
          nodeToReplace.replace(mentionNode);
        }
        mentionNode.select();
        closeMenu();
      });
    },
    [editor],
  );

  const checkForSlashTriggerMatch = useBasicTypeaheadTriggerMatch("/", {
    minLength: 0,
  });

  const checkForMentionMatch = useCallback(
    (text: string) => {
      if (checkForSlashTriggerMatch(text, editor) !== null) {
        return null;
      }
      return checkForAtSignMentions(text, 1);
    },
    [checkForSlashTriggerMatch, editor],
  );

  return (
    <LexicalTypeaheadMenuPlugin<MentionTypeaheadOption>
      onQueryChange={setQueryString}
      onSelectOption={onSelectOption}
      triggerFn={checkForMentionMatch}
      options={options}
      menuRenderFn={(
        anchorElementRef,
        { selectedIndex, selectOptionAndCleanUp, setHighlightedIndex },
      ) =>
        anchorElementRef.current && options.length > 0 ? (
          <Popover open>
            <PopoverPrimitive.Portal
              dir={dir}
              container={anchorElementRef.current}
            >
              <PopoverTrigger
                nativeButton={false}
                render={
                  <span
                    aria-hidden
                    className="pointer-events-none absolute inset-x-0 top-0 h-0"
                  />
                }
              />
              <PopoverContent
                dir={dir}
                side="bottom"
                align="start"
                sideOffset={6}
                initialFocus={false}
                className="w-auto overflow-hidden p-0"
              >
                <Command
                  value={
                    selectedIndex === null
                      ? ""
                      : (options[selectedIndex]?.name ?? "")
                  }
                  onValueChange={(nextValue) => {
                    const index = options.findIndex(
                      (option) => option.name === nextValue,
                    );
                    if (index >= 0) {
                      setHighlightedIndex(index);
                    }
                  }}
                  shouldFilter={false}
                >
                  <CommandList className="max-h-64 w-56">
                    {options.map((option) => (
                      <CommandItem
                        key={option.key}
                        ref={option.setRefElement}
                        value={option.name}
                        onSelect={() => selectOptionAndCleanUp(option)}
                      >
                        <User className="size-4 text-muted-foreground" />
                        <span className="truncate">{option.name}</span>
                      </CommandItem>
                    ))}
                  </CommandList>
                </Command>
              </PopoverContent>
            </PopoverPrimitive.Portal>
          </Popover>
        ) : null
      }
    />
  );
}

import { useEffect, useRef, useState } from "react";

import { type NodeKey, registerEventListener } from "lexical";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import {
  TableOfContentsPlugin as LexicalTableOfContentsPlugin,
  type TableOfContentsEntry,
} from "@lexical/react/LexicalTableOfContentsPlugin";
import type { HeadingTagType } from "@lexical/rich-text";

import { useTranslation } from "@/components/editor/plugins/i18n-plugin";
import {
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/components/ui/sidebar";
import { cn } from "@/lib/utils";

const INDENTS: Partial<Record<HeadingTagType, string>> = {
  h2: "ps-5",
  h3: "ps-8",
  h4: "ps-8",
  h5: "ps-8",
  h6: "ps-8",
};

function getScrollParent(element: HTMLElement | null): HTMLElement | null {
  let current = element?.parentElement ?? null;
  while (current) {
    const { overflowY } = getComputedStyle(current);
    if (overflowY === "auto" || overflowY === "scroll") {
      return current;
    }
    current = current.parentElement;
  }
  return null;
}

function TableOfContentsList({
  tableOfContents,
}: {
  tableOfContents: TableOfContentsEntry[];
}) {
  const [editor] = useLexicalComposerContext();
  const { t } = useTranslation();
  const [selectedKey, setSelectedKey] = useState<NodeKey>("");
  const suppressTrackingUntil = useRef(0);

  const scrollToNode = (key: NodeKey) => {
    editor.read("latest", () => {
      const domElement = editor.getElementByKey(key);
      if (domElement === null) {
        return;
      }
      suppressTrackingUntil.current = performance.now() + 1000;
      const scroller = getScrollParent(editor.getRootElement());
      if (scroller === null) {
        domElement.scrollIntoView({ behavior: "smooth", block: "start" });
      } else {
        const top =
          domElement.getBoundingClientRect().top -
          scroller.getBoundingClientRect().top +
          scroller.scrollTop;
        scroller.scrollTo({ top, behavior: "smooth" });
      }
      setSelectedKey(key);
    });
  };

  useEffect(() => {
    const rootElement = editor.getRootElement();
    const scroller = getScrollParent(rootElement);
    if (rootElement === null) {
      return;
    }

    let timerId: ReturnType<typeof setTimeout>;

    const updateSelection = () => {
      if (performance.now() < suppressTrackingUntil.current) {
        return;
      }
      const topBoundary =
        (scroller ?? rootElement).getBoundingClientRect().top + 16;
      let nextKey = tableOfContents[0]?.[0] ?? "";
      for (const [key] of tableOfContents) {
        const heading = editor.getElementByKey(key);
        if (heading === null) {
          continue;
        }
        if (heading.getBoundingClientRect().top <= topBoundary) {
          nextKey = key;
        } else {
          break;
        }
      }
      setSelectedKey(nextKey);
    };

    updateSelection();
    const onScroll = () => {
      clearTimeout(timerId);
      timerId = setTimeout(updateSelection, 50);
    };

    return registerEventListener(scroller ?? document, "scroll", onScroll);
  }, [editor, tableOfContents]);

  if (tableOfContents.length === 0) {
    return null;
  }

  return (
    <SidebarGroup>
      <SidebarGroupLabel>{t.tableOfContents}</SidebarGroupLabel>
      <SidebarGroupContent>
        <SidebarMenu>
          {tableOfContents.map(([key, text, tag]) => (
            <SidebarMenuItem key={key}>
              <SidebarMenuButton
                isActive={selectedKey === key}
                className={cn(INDENTS[tag])}
                onClick={() => scrollToNode(key)}
              >
                <span>{text}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

export function TableOfContentsPlugin() {
  return (
    <LexicalTableOfContentsPlugin>
      {(tableOfContents) => (
        <TableOfContentsList tableOfContents={tableOfContents} />
      )}
    </LexicalTableOfContentsPlugin>
  );
}

